def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform an action on a record."""
    role_id = user.get("ROLE_ID", "")

    for row in role_rows:
        if (
            row.get("role_id", "") != role_id
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        if action == "DELETE" and record.get("DEL_FLG", "") not in ("", "N"):
            return False

        if role_id == "ADMIN":
            return True

        scope = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user.get("TEAM_CD", "") == record.get("TEAM_CD", "")
        if scope == "OWN":
            return user.get("USR_ID", "") == record.get("OWNER_UID", "")
        return False

    return False
